<?php
require_once 'config/functions.php';
$id=(int)($_GET['id']??0);
$stmt=$conn->prepare("SELECT p.*,k.nama_kategori FROM produk p LEFT JOIN kategori k ON p.id_kategori=k.id_kategori WHERE p.id_produk=?");
$stmt->bind_param('i',$id);$stmt->execute();$p=$stmt->get_result()->fetch_assoc();
if(!$p){http_response_code(404);exit('Produk tidak ditemukan.');}
?>
